using Xunit;
using Moq;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.VectorData;
using Microsoft.Extensions.AI;
using Microsoft.SemanticKernel.Connectors.Qdrant;
using System;
using System.Linq;

namespace QdrantServiceCollectionExtensionsTests
{
    public class AddQdrantVectorStoreTests
    {
        [Fact]
        public void AddQdrantVectorStore_CallsGetServiceForIEmbeddingGenerator()
        {
            // Arrange
            var services = new ServiceCollection();

            var mockGenerator = new Mock<IEmbeddingGenerator>();
            services.AddTransient(_ => mockGenerator.Object);

            var serviceProvider = services.BuildServiceProvider();

            // Act
            services.AddQdrantVectorStore("http://localhost");

            var provider = services.BuildServiceProvider();

            // Assert
            var generator = provider.GetService<IEmbeddingGenerator>();
            Assert.NotNull(generator);
            Assert.Equal(mockGenerator.Object, generator);
        }
    }
}
